package e.e.a;
import android.app.*;import android.content.*;import java.io.*;import java.net.*;import java.util.*;
/** Cancellation owns the worker and its live connections, not only the service flag. */
public final class CacheControl110 {
 private static final Map<Object,Boolean> services=Collections.synchronizedMap(new WeakHashMap<>());
 public static void started(Object service){synchronized(services){if(!services.containsKey(service))services.put(service,true);}}
 public static boolean active(Object service){return Boolean.TRUE.equals(services.get(service));}
 static void deactivate(Object service){services.put(service,false);for(String field:new String[]{"q","g"})try{service.getClass().getField(field).setBoolean(service,false);}catch(Exception ignored){}}
 public static void destroyed(Object service){deactivate(service);cancel();}
 private static final Map<Thread,Job> jobs=new java.util.concurrent.ConcurrentHashMap<>();
 static final class Job {volatile boolean cancelled;final java.util.concurrent.atomic.AtomicBoolean finished=new java.util.concurrent.atomic.AtomicBoolean();String id="";final Set<Object> requests=Collections.newSetFromMap(new java.util.concurrent.ConcurrentHashMap<Object,Boolean>());final Set<java.io.Closeable> streams=Collections.newSetFromMap(new java.util.concurrent.ConcurrentHashMap<java.io.Closeable,Boolean>());final Set<HttpURLConnection> connections=Collections.newSetFromMap(new java.util.concurrent.ConcurrentHashMap<HttpURLConnection,Boolean>());}
 public static void register(Thread worker){Job job=new Job();try{job.id=String.valueOf(Class.forName("com.sauzask.nicoid.NicoidDownloadCache").getField("t").get(null));}catch(Exception ignored){}jobs.put(worker,job);Thread monitor=new Thread(()->{try{long until=System.currentTimeMillis()+5000;while(worker.getState()==Thread.State.NEW&&System.currentTimeMillis()<until)Thread.sleep(5);worker.join();}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{end(worker,job);}},"nicoid-cache-worker-watch");monitor.setDaemon(true);monitor.start();}
 public static void enter(Object service)throws IOException{synchronized(services){if(!active(service))throw new java.io.InterruptedIOException();enter();}}
 public static void request(Object request)throws IOException{check();Job job=jobs.get(Thread.currentThread());if(job!=null){job.requests.add(request);if(job.cancelled){abort(request);check();}}}
 static void abort(Object request){try{request.getClass().getMethod("abort").invoke(request);}catch(Exception ignored){}}
 public static void enter()throws IOException{try{if(!Class.forName("com.sauzask.nicoid.NicoidDownloadCache").getField("v").getBoolean(null))throw new java.io.InterruptedIOException();}catch(ReflectiveOperationException ignored){}if(!jobs.containsKey(Thread.currentThread()))register(Thread.currentThread());check();}
 public static void check()throws IOException{Job j=jobs.get(Thread.currentThread());if(Thread.currentThread().isInterrupted()||(j!=null&&j.cancelled))throw new java.io.InterruptedIOException("Cache acquisition cancelled");}
 public static void connection(HttpURLConnection c)throws IOException{check();Job j=jobs.get(Thread.currentThread());if(j!=null){j.connections.add(c);if(j.cancelled){c.disconnect();check();}}}
 public static void finish(){Thread worker=Thread.currentThread();Job job=jobs.get(worker);if(job!=null)end(worker,job);}
 static void end(Thread worker,Job job){if(!job.finished.compareAndSet(false,true))return;try{cleanup(job);}catch(Exception error){android.util.Log.w("nicoid-cache","Unable to clean interrupted media",error);}finally{jobs.remove(worker,job);}}
 static void cleanup(Job job){if(!job.cancelled||!job.id.matches("(?:sm|so|nm|ss)[0-9]+")||CacheFolders.context==null)return;String folder=CacheFolders.root(CacheFolders.context)+"/nicoid/nicoid_cache/";for(File f:new CacheFile(folder).listFiles())if(job.id.equals(CacheFolders.videoId(f.getName()))&&!f.getName().endsWith(".json")&&!f.getName().endsWith(".thm")&&!f.getName().endsWith(".xml")){CachePack.invalidate(f);f.delete();}CacheFolders.invalidateSummary(CacheFolders.context);}
 public static void stream(java.io.Closeable s)throws IOException{check();Job j=jobs.get(Thread.currentThread());if(j!=null){j.streams.add(s);if(j.cancelled){s.close();check();}}}
 public static boolean busy(){return !jobs.isEmpty();}
 public static void cancel(){List<Job> stopping=new ArrayList<>();for(Map.Entry<Thread,Job> e:jobs.entrySet()){e.getValue().cancelled=true;e.getKey().interrupt();stopping.add(e.getValue());}new Thread(()->{for(Job job:stopping){for(Object request:job.requests)abort(request);for(HttpURLConnection c:job.connections)c.disconnect();for(java.io.Closeable stream:job.streams)try{stream.close();}catch(IOException ignored){}}},"nicoid-cache-interrupt").start();}
 public static void stop(Context c){synchronized(services){for(Object service:services.keySet())deactivate(service);}cancel();try{Class<?> type=Class.forName("com.sauzask.nicoid.NicoidDownloadCache");type.getField("v").setBoolean(null,false);Object queue=type.getField("u").get(null);if(queue instanceof List)synchronized(queue){((List<?>)queue).clear();}}catch(Exception ignored){}c.stopService(new Intent().setClassName(c,"com.sauzask.nicoid.NicoidDownloadCache"));CacheProgress.stop();CacheFolders.invalidateSummary(c);}
 public static void dialog(Activity a){ThemeChoice.apply(a);a.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));AlertDialog d=UiDialogs.builder(PlaybackSession.dialogContext(a)).setTitle(PanelUi.tr(a,"キャッシュの取得を中断しますか？","Stop cache acquisition?","中斷快取下載？")).setMessage(PanelUi.tr(a,"進行中のキャッシュ取得を停止します。","Stops the current cache acquisition.","停止進行中的快取下載。" )).setPositiveButton(PanelUi.tr(a,"中断","Stop","中斷"),(x,w)->stop(a)).setNegativeButton(UiStrings.translate("キャンセル"),null).create();d.setOnDismissListener(x->a.finish());UiDialogs.show(d);d.getButton(-2).setTextColor(PanelUi.ink(a));}

 public static void settings(android.preference.PreferenceActivity a){android.preference.Preference p=a.findPreference("cache_all_delete");if(p!=null)p.setOnPreferenceClickListener(v->{UiDialogs.show(UiDialogs.builder(PlaybackSession.dialogContext(a)).setTitle(UiStrings.translate("キャッシュをすべて削除しますか？")).setPositiveButton(UiStrings.translate("削除"),(x,w)->remove(a,null,null)).setNegativeButton(UiStrings.translate("キャンセル"),null).create());return true;});}
 static void remove(Activity a,String id,Runnable done){boolean related=id==null;for(Job job:jobs.values())if(id!=null&&id.equals(job.id))related=true;if(related)stop(a);new Thread(()->{boolean ok=false;try{await();ok=delete(a,id);}catch(Exception ignored){}boolean success=ok;a.runOnUiThread(()->{if(a.isFinishing())return;if(success){if(done!=null)done.run();android.widget.Toast.makeText(a,UiStrings.translate("削除しました"),0).show();}else android.widget.Toast.makeText(a,UiStrings.translate("削除に失敗しました"),1).show();});},"nicoid-cache-delete").start();}
 static void await()throws IOException{long until=System.currentTimeMillis()+10000;while(busy()){if(System.currentTimeMillis()>until)throw new IOException("Cache worker still stopping");try{Thread.sleep(25);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new java.io.InterruptedIOException();}}}
 static boolean delete(Context c,String id)throws IOException{if(id!=null&&!id.matches("(?:sm|so|nm|ss)[0-9]+"))return false;String folder=CacheFolders.root(c)+"/nicoid/nicoid_cache/";boolean ok=true;for(File f:new CacheFile(folder).listFiles())if(CacheFolders.videoId(f.getName())!=null&&(id==null||id.equals(CacheFolders.videoId(f.getName())))){CachePack.invalidate(f);if(f.exists()&&!f.delete())ok=false;}CacheFolders.invalidateSummary(c);return ok;}
}
